export interface BlogSection {
  title?: string
  content?: string | string[]
  items?: string[]
  rows?: Array<{ [key: string]: string }>
  columns?: string[]
  downloadCta?: {
    label: string
    href: string
    description?: string
  }
  isTldr?: boolean
  faqs?: Array<{ q: string; a: string }>
  image?: string
  imageCaption?: string
  imagePlaceholder?: boolean
}

export interface BlogPost {
  category: string
  title: string
  intro: string
  seoTitle?: string
  publishDate: string
  /** ISO 8601 date (e.g. '2026-06-10'). Set only when this post's content is substantively
   * updated — never for cosmetic date-label changes. EN block is the source of truth;
   * used for JSON-LD dateModified and sitemap lastmod. Falls back to publishDate if unset. */
  dateModified?: string
  readTime: string
  sections: Record<string, BlogSection>
  metaDescription?: string
  educationalLevel?: string
  heroImage?: string
  heroComponent?: string
  faqSchema?: Record<string, unknown>
  howToSchema?: Record<string, unknown>
  itemListSchema?: Record<string, unknown>
  freshness_tier?: 'evergreen' | 'semi_annual' | 'annual' | 'monthly'
  next_refresh_due?: string
  last_full_refresh?: string
  next_seo_review_due?: string
  last_seo_review?: string
  current_models_mentioned?: string[]
  current_benchmarks_used?: string[]
  current_hardware_mentioned?: string[]
  archive_after?: string
  specific_year?: number
}

